{
        if (zend_ini_parse_bool(new_value)) {
                zend_error(E_DEPRECATED, "auto_detect_line_endings is deprecated");
        }
        return OnUpdateBool(entry, new_value, mh_arg1, mh_arg2, mh_arg3, stage);
}

